public static TFMTablesProvider instance()
{
    TFMTablesProvider   singleton;

    System.Runtime.Caching.ObjectCache memCache = System.Runtime.Caching.MemoryCache::Default;
    str cacheId = classId2Name(classIdGet(singleton));
    singleton = memCache.Get(cacheId);
    if(!singleton)
    {
        singleton = new TFMTablesProvider();
        memCache.Add(cacheId, singleton, new System.Runtime.Caching.CacheItemPolicy());
    }

    return singleton;
}

    private void new()
    {
        tablesAllowed = new Map(Types::Int64,Types::Enum);
	}

public boolean isTableAllowed(TableId _id)
{
    SysDictTable sdt;
    TableGroup		tg;

    if (tablesAllowed.exists(_id))
    {
        return tablesAllowed.lookup(_id);
    }
    sdt = new SysDictTable(_id);

    tg = sdt.tableGroup();

    tablesAllowed.insert(_id, tg != TableGroup::Transaction);

    return tablesAllowed.lookup(_id);
}
